// src/site.ts
var BRAND_NAME = "GainUtility";
var SITE_URL = "https://gainutility.com"?.replace(/\/$/, "") || "https://gainutility.com";
var CHROME_EXTENSION_STORE_URL = import.meta.env?.VITE_CHROME_EXTENSION_STORE_URL?.replace(/\/$/, "") || "";
var SITE_TAGLINE = "Free Browser-Based Tools";
var DEFAULT_TITLE = `${BRAND_NAME} \u2014 ${SITE_TAGLINE}`;
var absoluteUrl = (path = "/") => {
  const cleanPath = path.startsWith("/") ? path : `/${path}`;
  return `${SITE_URL}${cleanPath === "/" ? "/" : cleanPath}`;
};
var toolPath = (toolId) => `/tools/${toolId}`;
var studioPath = (studioId) => `/studios/${studioId}`;

