var localizedToolName = (toolId, locale, fallbackName) => {
  if (locale === DEFAULT_LOCALE || !isSupportedLocale(locale)) return fallbackName;
  return TOOL_LOCALE_NAMES[toolId]?.[locale] ?? fallbackName;
};
var localizedToolSlug = (toolId, locale, fallbackEnglishSlug) => {
  if (locale === DEFAULT_LOCALE || !isSupportedLocale(locale)) return fallbackEnglishSlug;
  const hand = TOOL_LOCALE_SLUGS[toolId]?.[locale];
  if (hand) return hand;
  const localized = TOOL_LOCALE_NAMES[toolId]?.[locale];
  if (localized) return slugify(localized);
  return slugify(fallbackEnglishSlug);
};
var localizedStudioName = (studioId, locale, fallback) => {
  if (locale === DEFAULT_LOCALE || !isSupportedLocale(locale)) return fallback;
  return STUDIO_LOCALE_NAMES[studioId]?.[locale] ?? fallback;
};
