var localizedHubOverlay = (slug, locale) => {
  const overlays = HUB_LOCALIZED[slug];
  if (!overlays) return void 0;
  const code = (locale || "en").toLowerCase();
  if (code === "es-co") return overlays["es-co"] ?? overlays["es-mx"];
  return overlays[code];
};

