var localizedSeoEntry = (en, locale = DEFAULT_LOCALE) => {
  const overlay = localizedHubOverlay(en.slug, locale);
  if (!overlay) return en;
  const code = locale.toLowerCase() === "es-co" ? "es-mx" : locale;
  const enName = new Map(en.relatedTools.map((r2) => [r2.id, r2.name]));
  const tpl = RELATED_DESC_TEMPLATE[code] ?? RELATED_DESC_TEMPLATE.en;
  return {
    ...en,
    category: overlay.category,
    title: overlay.title,
    description: overlay.description,
    intro: overlay.intro,
    useCases: overlay.useCases,
    steps: overlay.steps,
    faq: overlay.faq,
    breadcrumbs: overlay.breadcrumbs.map((c, i) => ({
      name: c.name,
      url: localizedCrumbPath(locale, en.breadcrumbs[i]?.url ?? c.url)
    })),
    relatedTools: en.relatedTools.map((r2) => {
      const name = localizedToolName(r2.id, code, enName.get(r2.id) ?? r2.id);
      return { id: r2.id, name, description: tpl.replace("{name}", name) };
    })
  };
};

