var normalizeHex = (value) => {
  let v = value.trim().replace(/^#/, "");
  if (!/^[a-f\d]+$/i.test(v)) return null;
  if (v.length === 3) v = v[0] + v[0] + v[1] + v[1] + v[2] + v[2];
  if (v.length !== 6) return null;
  return `#${v.toUpperCase()}`;
};
var hexToRgb = (hex) => {
  const n = normalizeHex(hex);
  if (!n) return null;
  const r2 = parseInt(n.slice(1, 3), 16);
  const g = parseInt(n.slice(3, 5), 16);
  const b = parseInt(n.slice(5, 7), 16);
  return { r: r2, g, b };
};
var rgbToHsl = (r2, g, b) => {
  r2 /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r2, g, b);
  const min = Math.min(r2, g, b);
  let h = 0;
  let s = 0;
  const l = (max + min) / 2;
  const d = max - min;
  if (d !== 0) {
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r2:
        h = (g - b) / d + (g < b ? 6 : 0);
        break;
      case g:
        h = (b - r2) / d + 2;
        break;
      default:
        h = (r2 - g) / d + 4;
    }
    h *= 60;
  }
  return { h: Math.round(h), s: Math.round(s * 100), l: Math.round(l * 100) };
};
var hexToHsl = (hex) => {
  const rgb = hexToRgb(hex);
  return rgb ? rgbToHsl(rgb.r, rgb.g, rgb.b) : null;
};
var ENCODED_RE = /^([0-9a-f]{6})(-([0-9a-f]{6}))+$/i;
var paletteFromSlug = (slug) => {
  if (!ENCODED_RE.test(slug)) return null;
  return slug.split("-").map((c) => normalizeHex(c)).filter(Boolean);
};
var paletteName = (hexes) => {
  const first = hexes[0];
  const hsl = first ? hexToHsl(first) : null;
  if (!hsl) return "Custom Palette";
  const hueName = hsl.h < 15 || hsl.h >= 345 ? "Crimson" : hsl.h < 45 ? "Amber" : hsl.h < 75 ? "Olive" : hsl.h < 160 ? "Pine" : hsl.h < 200 ? "Seafoam" : hsl.h < 250 ? "Azure" : hsl.h < 290 ? "Indigo" : hsl.h < 330 ? "Violet" : "Rose";
  const tone = hsl.l > 75 ? "Mist" : hsl.l < 40 ? "Deep" : "Coast";
  return `${tone} ${hueName}`;
};

