var BLOG_SLUG_TO_ARTICLE = Object.fromEntries(
  BLOG_ARTICLES.map((a) => [a.slug, a])
);
var ACTIVE_BLOG_CATEGORIES = [
  "PDF",
  "Images",
  "SEO",
  "Developer",
  "Productivity"
].filter((c) => BLOG_ARTICLES.some((a) => a.category === c));
var articleBySlug = (slug) => BLOG_SLUG_TO_ARTICLE[slug];
var articleLocalized = (article, locale = DEFAULT_LOCALE) => {
  if (locale === DEFAULT_LOCALE) return article;
  const localized = article.localized?.[locale];
  return localized ? { ...article, ...localized } : article;
};

